def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    h = max(0, int(horizon))
    if h == 0:
        return []
    vals = []
    for v in history:
        if isinstance(v, (int, float)):
            x = float(v)
            if math.isfinite(x):
                vals.append(x)
    if not vals:
        return [0.0] * h
    def med(seq):
        a = sorted(seq)
        m = len(a)
        if m == 0:
            return 0.0
        return a[m // 2] if m % 2 else 0.5 * (a[m // 2 - 1] + a[m // 2])
    n = len(vals)
    local_window = min(n, 24)
    local = med(vals[-local_window:])
    period = 24
    if n < 4 * period:
        return [local] * h
    def seasonal_at(data, step):
        m = len(data)
        phase_values = []
        for j in range(1, 5):
            idx = m + step - j * period
            if 0 <= idx < m:
                phase_values.append(data[idx])
        phase = med(phase_values) if phase_values else med(data[-min(period, m):])
        recent = data[-period:]
        previous = data[-4 * period:-period]
        shift = med(recent) - med(previous) if previous else 0.0
        deviations = [abs(x - med(recent)) for x in recent]
        scale = med(deviations)
        bound = max(scale, 1e-12)
        shift = max(-bound, min(bound, shift))
        return phase + 0.5 * shift
    ratios = []
    for origin in (n - 3 * period, n - 2 * period, n - period):
        if origin < 3 * period:
            continue
        prefix = vals[:origin]
        baseline = med(prefix[-period:])
        seasonal_errors = []
        baseline_errors = []
        for k in range(period):
            target = vals[origin + k]
            seasonal_errors.append(abs(target - seasonal_at(prefix, k)))
            baseline_errors.append(abs(target - baseline))
        be = sum(baseline_errors)
        if be > 0.0:
            ratios.append(sum(seasonal_errors) / be)
    enabled = len(ratios) == 3 and sum(r <= 0.90 for r in ratios) >= 2 and max(ratios) <= 1.05
    if enabled:
        middle = med(ratios)
        weight = max(0.25, min(0.80, 1.5 * (1.0 - middle)))
    else:
        weight = 0.0
    out = []
    for k in range(h):
        if k < period:
            seasonal = seasonal_at(vals, k)
        else:
            seasonal = out[k - period]
        y = (1.0 - weight) * local + weight * seasonal
        if not math.isfinite(y):
            y = local
        out.append(float(y))
    return out
